window.CODE = Object.assign(window.CODE || {}, {"ch19/agno_agent.py":"\"\"\"The clinic helpdesk agent in Agno: model, tools and instructions in one object.\n\nAgno agents are plain Python objects. The loop (call model, run tools, repeat) is built in,\nlike create_agent in Chapter 13.\n\nRun:  pip install agno\n      python agno_agent.py\n\"\"\"\nimport os\nimport sys\nfrom pathlib import Path\n\nfrom agno.agent import Agent\nfrom agno.tools import tool\nfrom dotenv import load_dotenv\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch09\"))\nimport clinic  # noqa: E402\n\nload_dotenv()\n\n\ndef make_model():\n    \"\"\"Agno has a class per provider. Switch with PROVIDER in .env.\"\"\"\n    if os.getenv(\"PROVIDER\", \"openai\") == \"anthropic\":\n        from agno.models.anthropic import Claude\n        return Claude(id=os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\"))\n    from agno.models.openai import OpenAIChat\n    return OpenAIChat(id=os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"))\n\n\n# Plain functions become tools; the docstring and type hints become the schema.\ndef get_doctor_schedule(department: str) -> dict:\n    \"\"\"Look up which doctors in a hospital department see patients on which weekdays.\n\n    Args:\n        department: Department name, for example cardiology.\n    \"\"\"\n    return clinic.get_doctor_schedule(department)\n\n\n@tool(requires_confirmation=True)          # the run PAUSES until a person confirms\ndef request_appointment(doctor: str, day: str, patient_name: str) -> dict:\n    \"\"\"Create an appointment request for staff to approve. Use only after the patient asks to book.\n\n    Args:\n        doctor: Exact doctor name, e.g. Dr Rao.\n        day: Weekday, e.g. Thu.\n        patient_name: The patient's full name.\n    \"\"\"\n    return clinic.request_appointment(doctor, day, patient_name)\n\n\nhelpdesk = Agent(\n    name=\"City Clinic helpdesk\",\n    model=make_model(),\n    tools=[get_doctor_schedule, request_appointment],\n    instructions=[\"Always check the schedule with a tool before answering about availability. Never guess.\",\n                  \"Never give medical advice. For emergencies say: go to Emergency or call 108.\",\n                  \"Keep replies short and friendly.\"],\n    tool_call_limit=5,                     # the loop budget\n    markdown=False,\n)\n\nif __name__ == \"__main__\":\n    run = helpdesk.run(\"Is any cardiologist free on Thursday?\")\n    print(\"Answer:\", run.content)\n    print(\"Tools used:\", [(t.tool_name, t.tool_args) for t in run.tools])\n    print(\"Tokens:\", run.metrics.input_tokens, \"in,\", run.metrics.output_tokens, \"out\")\n\n    run = helpdesk.run(\"Please book Dr Rao on Thursday for Asha Verma.\")\n    if run.is_paused:                                    # waiting for a person\n        for t in run.tools_requiring_confirmation:\n            print(f\"\\nNeeds approval: {t.tool_name}({t.tool_args})\")\n            t.confirmed = True                           # staff said yes (False would decline it)\n        run = helpdesk.continue_run(run_response=run)\n    print(\"Answer:\", run.content)\n","ch19/agno_memory_knowledge.py":"\"\"\"Agno storage, conversation history and knowledge (RAG) in a few lines.\n\ndb=SqliteDb(...)             saves every session and run (PostgresDb in production)\nadd_history_to_context=True  sends the last few runs of THIS session to the model\nknowledge=Knowledge(...)     a vector store of your documents; search_knowledge=True gives the\n                             agent a search tool, so it decides when to look things up (agentic RAG)\n\nRun:  pip install agno chromadb\n      python agno_memory_knowledge.py\n\"\"\"\nfrom pathlib import Path\n\nfrom agno.agent import Agent\nfrom agno.db.sqlite import SqliteDb\nfrom agno.knowledge.embedder.openai import OpenAIEmbedder\nfrom agno.knowledge.knowledge import Knowledge\nfrom agno.vectordb.chroma import ChromaDb\nfrom agno_agent import get_doctor_schedule, make_model\n\nHERE = Path(__file__).resolve().parent\n\nknowledge = Knowledge(\n    name=\"City Clinic policies\",\n    vector_db=ChromaDb(collection=\"clinic_policies\", path=str(HERE / \"tmp\" / \"chroma\"), persistent_client=True,\n                       embedder=OpenAIEmbedder(id=\"text-embedding-3-small\")),\n    # No OpenAI key? Use agno.knowledge.embedder.sentence_transformer.SentenceTransformerEmbedder()\n)\n\nagent = Agent(\n    name=\"City Clinic helpdesk\",\n    model=make_model(),\n    tools=[get_doctor_schedule],\n    knowledge=knowledge,\n    search_knowledge=True,                   # adds a search_knowledge_base tool\n    db=SqliteDb(db_file=str(HERE / \"tmp\" / \"agno.db\")),\n    add_history_to_context=True,\n    num_history_runs=3,                      # only the last 3 exchanges are sent: a built-in trim\n    instructions=[\"Answer policy questions from the knowledge base and cite the document.\",\n                  \"Use get_doctor_schedule for doctors' days. Keep replies short.\"],\n)\n\nif __name__ == \"__main__\":\n    for doc in sorted((HERE.parent / \"ch07\" / \"docs\").glob(\"*.md\")):\n        knowledge.insert(path=str(doc), metadata={\"doc\": doc.stem}, skip_if_exists=True)   # load, chunk, embed, store\n\n    session = {\"user_id\": \"UHID-1001\", \"session_id\": \"asha-chat-1\"}\n    for q in [\"Can my 10-year-old visit the ICU?\", \"And what are the ICU visiting times?\"]:\n        run = agent.run(q, **session)\n        print(f\"Q: {q}\\n   tools: {[t.tool_name for t in run.tools]}\\n   A: {run.content}\\n\")\n\n    # A NEW agent object, same database: the conversation is still there\n    later = Agent(model=make_model(), db=SqliteDb(db_file=str(HERE / \"tmp\" / \"agno.db\")))\n    print(\"Runs saved in this session:\", len(later.get_session(session_id=\"asha-chat-1\").runs))\n","ch19/agno_production.py":"\"\"\"Agno in production: guardrails, tool hooks for auditing, and serving with AgentOS.\n\npre_hooks   run on the input before the model sees it (guardrails: PII, prompt injection)\ntool_hooks  wrap every tool call (logging, timing, permission checks)\nAgentOS     turns agents, teams and workflows into a FastAPI app with run, session and memory endpoints\n\nRun:  python agno_production.py          then open http://localhost:7777/docs\n\"\"\"\nimport logging\nimport time\n\nfrom agno.agent import Agent\nfrom agno.db.sqlite import SqliteDb\nfrom agno.guardrails import PIIDetectionGuardrail, PromptInjectionGuardrail\nfrom agno.os import AgentOS\nfrom agno_agent import get_doctor_schedule, make_model, request_appointment\n\nlog = logging.getLogger(\"audit\")\nlogging.basicConfig(level=logging.INFO, format=\"%(name)s %(message)s\")\n\n\ndef audit(function_name: str, function_call, arguments: dict):\n    \"\"\"A tool hook: runs around every tool call. Log the action, not the patient's details.\"\"\"\n    start = time.perf_counter()\n    result = function_call(**arguments)\n    safe_args = {k: v for k, v in arguments.items() if k != \"patient_name\"}\n    log.info(\"tool=%s args=%s ms=%.0f\", function_name, safe_args, (time.perf_counter() - start) * 1000)\n    return result\n\n\nhelpdesk = Agent(\n    id=\"helpdesk\",\n    name=\"City Clinic helpdesk\",\n    model=make_model(),\n    tools=[get_doctor_schedule, request_appointment],\n    pre_hooks=[PIIDetectionGuardrail(mask_pii=True,                         # mask emails, phones, cards\n                                     custom_patterns={\"aadhaar\": r\"\\b\\d{4}\\s?\\d{4}\\s?\\d{4}\\b\"}),\n               PromptInjectionGuardrail()],                                  # block \"ignore your instructions\"\n    tool_hooks=[audit],\n    tool_call_limit=5,\n    db=SqliteDb(db_file=\"tmp/agno.db\"),\n    add_history_to_context=True,\n    instructions=[\"Use tools; never guess schedules. Never give medical advice. Keep replies short.\"],\n)\n\nagent_os = AgentOS(id=\"clinic-os\", agents=[helpdesk])\napp = agent_os.get_app()                     # a FastAPI app: deploy it like Chapter 5's API\n\nif __name__ == \"__main__\":\n    agent_os.serve(app=\"agno_production:app\", port=7777)\n","ch19/teams_workflows.py":"\"\"\"Agno Teams (agents that cooperate) and Workflows (fixed steps you control).\n\nTeam      the leader model decides which member(s) handle a request\n          mode=\"route\": pick ONE member and return its answer;  \"coordinate\": split work and combine\nWorkflow  your code decides the order: steps run one after another; any step can stop the run\n\nRun:  python teams_workflows.py\n\"\"\"\nfrom agno.agent import Agent\nfrom agno.team import Team\nfrom agno.workflow import Step, StepInput, StepOutput, Workflow\nfrom agno_agent import get_doctor_schedule, make_model\n\nEMERGENCY_WORDS = (\"chest pain\", \"breathless\", \"unconscious\", \"bleeding\")\n\nscheduler = Agent(name=\"Scheduler\", role=\"Answers questions about which days doctors work\",\n                  model=make_model(), tools=[get_doctor_schedule],\n                  instructions=[\"Always use get_doctor_schedule. One sentence.\"])\nbilling = Agent(name=\"Billing\", role=\"Answers questions about fees and bills\",\n                model=make_model(),\n                instructions=[\"OPD registration is Rs 100, valid 7 days for the same doctor. One sentence.\"])\n\n# ---------------------------------------------------------------- a team: the model routes\nfront_desk = Team(name=\"Front desk\", mode=\"route\", model=make_model(), members=[scheduler, billing],\n                  instructions=[\"Send each patient question to the one member best suited to answer it.\"])\n\n\n# ---------------------------------------------------------------- a workflow: code decides\ndef safety_check(step_input: StepInput) -> StepOutput:\n    \"\"\"A plain function step: emergencies never reach a model.\"\"\"\n    if any(w in str(step_input.input).lower() for w in EMERGENCY_WORDS):\n        return StepOutput(content=\"Please go to Emergency now or call 108.\", stop=True)   # stop the workflow\n    return StepOutput(content=step_input.input)\n\n\nhelpdesk_flow = Workflow(name=\"Helpdesk flow\", steps=[\n    Step(name=\"safety\", executor=safety_check),\n    Step(name=\"front desk\", team=front_desk),\n])\n\nif __name__ == \"__main__\":\n    for q in [\"Which days does Dr Khan work?\", \"How much is the OPD fee?\", \"My father has chest pain\"]:\n        out = helpdesk_flow.run(q)\n        print(f\"Q: {q}\\n   steps: {[s.step_name for s in out.step_results]}\\n   A: {out.content}\\n\")\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
